<script setup lang="ts">
import { computed } from 'vue'
import type { Permission } from '../types'
const props=defineProps<{items:Permission[];modelValue:string[];disabled?:boolean}>()
const emit=defineEmits<{ 'update:modelValue':[value:string[]] }>()
const groups=computed(() => props.items.filter(p => p.permission_type === 'menu').map(menu => ({menu,operations:props.items.filter(p => p.parent_code === menu.code)})))
function toggle(code:string,selected:boolean) { emit('update:modelValue',selected ? [...new Set([...props.modelValue,code])] : props.modelValue.filter(c => c!==code)) }
function setGroup(codes:string[],checked:boolean) { emit('update:modelValue',checked ? [...new Set([...props.modelValue,...codes])] : props.modelValue.filter(c => !codes.includes(c))) }
</script>
<template><div class="permission-picker"><details v-for="(group,index) in groups" :key="group.menu.code" class="permission-group" :open="index===0"><summary><strong>{{group.menu.name}}</strong><span class="muted num">{{[group.menu.code,...group.operations.map(p=>p.code)].filter(code=>modelValue.includes(code)).length}} / {{group.operations.length+1}} 项</span></summary><div class="permission-group-head"><span class="muted">菜单与操作独立配置</span><button type="button" class="text-button" :disabled="disabled" @click="setGroup([group.menu.code,...group.operations.map(p=>p.code)],!([group.menu.code,...group.operations.map(p=>p.code)].every(code=>modelValue.includes(code))))">{{ [group.menu.code,...group.operations.map(p=>p.code)].every(code=>modelValue.includes(code)) ? '清除本组' : '选择本组' }}</button></div><label class="checkbox-row menu-permission"><input type="checkbox" :checked="modelValue.includes(group.menu.code)" :disabled="disabled" @change="toggle(group.menu.code,($event.target as HTMLInputElement).checked)"/><span>显示{{ group.menu.name }}菜单</span></label><div class="permission-options"><label v-for="item in group.operations" :key="item.code" class="checkbox-row"><input type="checkbox" :checked="modelValue.includes(item.code)" :disabled="disabled" @change="toggle(item.code,($event.target as HTMLInputElement).checked)"/><span>{{ item.name }}</span></label></div></details></div></template>
